export const ls = new Command('ls')
    .description('list all running apps')
    .action(() => {
        try {
            const processManager = new ProcessManager()
            const processes = processManager.listRunningProcesses()

            if (processes.length === 0) {
                console.log('No running processes found')
                return
            }

            console.log('Running processes:')
            for (const process of processes) {
                if (process.isRunning) {
                    console.log(`- ${process.name} (pid: ${process.pid})`)
                } else {
                    console.warn(`- ${process.name} (pid: ${process.pid}) is not running`)
                }
            }
        } catch (error: unknown) {
            const err = error as Error
            console.error(`Error: ${err.message}`)
            process.exit(1)
        }
    })

import { Command } from 'commander'
import { isAnyTuiActive, writeReloadSignal, waitForReloadResult, clearReloadSignal } from '../services/IpcSignal.js'

// Stopping apps removed from the config can take a while.
const RELOAD_TIMEOUT_MS = 15000

export const reload = new Command('reload')
    .description('reload the config in the active TUI, same as pressing r there')
    .action(async () => {
        if (!isAnyTuiActive()) {
            console.error('No active TUI session found. Reload applies to a TUI started with --no-daemon')
            process.exit(1)
        }
        const timestamp = writeReloadSignal()
        const result = await waitForReloadResult(timestamp, RELOAD_TIMEOUT_MS)
        if (!result) {
            // The failure is reported now, so the reload must not happen later.
            clearReloadSignal()
            console.warn('Reload signal sent but the TUI did not report a result within timeout. A TUI started before pomitu had this command ignores it, so restart that TUI')
            process.exit(1)
        }
        if (result.ok) {
            console.log(result.message)
        } else {
            console.error(result.message)
            process.exit(1)
        }
    })

import { spawn as crossSpawn } from 'cross-spawn'
import { ChildProcess, spawn as nodeSpawn } from 'node:child_process'
import { parse } from 'shell-quote'
import * as fs from 'node:fs'
import {
    getProcessLogOutFilePath,
    getProcessLogErrorFilePath,
    pidIsRunning,
    getFileNameFriendlyName,
} from '../helpers.js'
import { PidManager } from './PidManager.js'
import { LogManager } from './LogManager.js'
import type { AppConfig } from './ConfigManager.js'

export interface ProcessInfo {
    name: string
    pid: number
    isRunning: boolean
}

export interface StartOptions {
    daemon?: boolean
    clearLogs?: boolean
}

export interface StopOptions {
    quiet?: boolean
}

function killProcess(pid: number): Promise<void> {
    return new Promise((resolve, reject) => {
        if (process.platform === 'win32') {
            const killer = nodeSpawn('taskkill', ['/F', '/T', '/PID', String(pid)])
            killer.on('close', (code) => code === 0 ? resolve() : reject(new Error(`taskkill exited with ${code}`)))
            killer.on('error', reject)
        } else {
            try {
                process.kill(pid)
                resolve()
            } catch (err) {
                reject(err)
            }
        }
    })
}

export class ProcessManager {
    private pidManager = new PidManager()
    private logManager = new LogManager()

    async startApp(app: AppConfig, options: StartOptions = {}): Promise<void> {
        const isDaemon = options.daemon ?? true

        if (isDaemon) {
            console.log(`Starting: ${app.name} (${app.cwd})`)
        }

        if (!fs.existsSync(app.cwd)) {
            throw new Error(`Directory ${app.cwd} does not exist`)
        }

        const run = parse(app.run) as string[]
        if (!run.length) {
            throw new Error(`Invalid run command for ${app.name}: ${app.run}`)
        }

        const fileNameFriendAppName = getFileNameFriendlyName(app.name)

        // Check if process is already running and stop it
        await this.stopIfRunning(app.name)

        // Clear logs if requested
        if (options.clearLogs) {
            this.logManager.clearAppLogs(fileNameFriendAppName)
        }

        // Start the process
        const process = await this.spawnProcess(app, run, options.daemon ?? true)

        // Save PID
        this.pidManager.savePid(fileNameFriendAppName, process.pid!)

        if (isDaemon) {
            console.log(`Started: ${app.name} with pid ${process.pid}`)
        }
    }

    async stopApp(name: string, options: StopOptions = {}): Promise<boolean> {
        const quiet = options.quiet ?? false
        const fileNameFriendlyName = getFileNameFriendlyName(name)
        const pid = this.pidManager.getPid(fileNameFriendlyName)

        if (!pid) {
            return false
        }

        if (!pidIsRunning(pid)) {
            console.warn(`${name} with pid ${pid} is not running`)
            this.pidManager.removePid(fileNameFriendlyName)
            return false
        }

        if (!quiet) {
            console.log(`Stopping ${name} with pid ${pid}`)
        }

        try {
            await killProcess(pid)
            this.pidManager.removePid(fileNameFriendlyName)
            if (!quiet) {
                console.log(`${name} with pid ${pid} stopped`)
            }
            return true
        } catch (error: unknown) {
            const err = error as Error
            console.error(`Error stopping ${name} with pid ${pid}: ${err.message}`)
            return false
        }
    }

    listRunningProcesses(): ProcessInfo[] {
        const pidFiles = this.pidManager.getAllPidFiles()
        const processes: ProcessInfo[] = []

        for (const pidFile of pidFiles) {
            const appName = pidFile.replace('.pid', '')
            const pid = this.pidManager.getPid(appName)

            if (pid) {
                processes.push({
                    name: appName,
                    pid,
                    isRunning: pidIsRunning(pid)
                })
            }
        }

        return processes
    }

    private async stopIfRunning(appName: string): Promise<void> {
        const fileNameFriendAppName = getFileNameFriendlyName(appName)
        const existingPid = this.pidManager.getPid(fileNameFriendAppName)

        if (existingPid && pidIsRunning(existingPid)) {
            console.warn(`Process ${appName} is already running with pid ${existingPid}`)
            console.log(`Stopping ${appName} at pid ${existingPid}`)

            try {
                await killProcess(existingPid)
            } catch (error: unknown) {
                const err = error as Error
                console.error(`Error stopping ${appName}: ${err.message}`)
            }
        }

        this.pidManager.removePid(fileNameFriendAppName)
    }

    private async spawnProcess(app: AppConfig, command: string[], daemon: boolean): Promise<ChildProcess> {
        const fileNameFriendAppName = getFileNameFriendlyName(app.name)
        const stdoutPath = getProcessLogOutFilePath(fileNameFriendAppName)
        const stderrPath = getProcessLogErrorFilePath(fileNameFriendAppName)

        const stdout = fs.openSync(stdoutPath, 'a')
        const stderr = fs.openSync(stderrPath, 'a')

        return new Promise((resolve, reject) => {
            const startedProcess = crossSpawn(command[0], command.slice(1), {
                cwd: app.cwd,
                stdio: ['ignore', stdout, stderr],
                detached: daemon,
            })

            startedProcess.on('error', (error) => {
                reject(new Error(`Error starting ${app.name}: ${error.message}`))
            })

            startedProcess.on('spawn', () => {
                if (daemon) {
                    startedProcess.unref()
                }
                resolve(startedProcess)
            })
        })
    }
}

import { Command } from 'commander'
import { ProcessManager } from '../services/index.js'
import { isTuiActive, writeSignal, waitForPidState } from '../services/IpcSignal.js'

export const stop = new Command('stop')
    .description('stop a running app or all apps')
    .argument('<name>', 'name of the app to stop or "all" to stop all apps')
    .action(async (name) => {
        try {
            const processManager = new ProcessManager()

            if (name === 'all') {
                const runningProcesses = processManager.listRunningProcesses()
                let stoppedCount = 0

                for (const proc of runningProcesses) {
                    if (isTuiActive(proc.name)) {
                        writeSignal(proc.name, 'stop')
                        const confirmed = await waitForPidState(proc.name, 'absent')
                        if (confirmed) stoppedCount++
                    } else {
                        const success = await processManager.stopApp(proc.name)
                        if (success) stoppedCount++
                    }
                }

                if (stoppedCount === 0) {
                    console.warn('No running processes found')
                } else {
                    console.log(`Stopped ${stoppedCount} process(es)`)
                }
            } else {
                if (isTuiActive(name)) {
                    writeSignal(name, 'stop')
                    const confirmed = await waitForPidState(name, 'absent')
                    if (confirmed) {
                        console.log(`Stopped ${name}`)
                    } else {
                        console.warn(`Stop signal sent but could not confirm ${name} stopped within timeout`)
                    }
                } else {
                    const success = await processManager.stopApp(name)
                    if (!success) {
                        console.warn(`No running process found for ${name}`)
                    }
                }
            }
        } catch (error: unknown) {
            const err = error as Error
            console.error(`Error: ${err.message}`)
            process.exit(1)
        }
    })

import * as fs from 'node:fs'
import { getPomituPidsDirectory } from '../helpers.js'
import * as path from 'node:path'

export class PidManager {
    private pidsDirectory: string

    constructor() {
        this.pidsDirectory = getPomituPidsDirectory()
    }

    savePid(appName: string, pid: number): void {
        const pidFilePath = this.getPidFilePath(appName)
        fs.writeFileSync(pidFilePath, pid.toString())
    }

    getPid(appName: string): number | null {
        const pidFilePath = this.getPidFilePath(appName)

        if (!fs.existsSync(pidFilePath)) {
            return null
        }

        try {
            const pidContent = fs.readFileSync(pidFilePath, 'utf-8')
            return parseInt(pidContent)
        } catch {
            return null
        }
    }

    removePid(appName: string): void {
        const pidFilePath = this.getPidFilePath(appName)

        if (fs.existsSync(pidFilePath)) {
            fs.unlinkSync(pidFilePath)
        }
    }

    getAllPidFiles(): string[] {
        if (!fs.existsSync(this.pidsDirectory)) {
            return []
        }

        return fs.readdirSync(this.pidsDirectory).filter(file => file.endsWith('.pid') && !file.endsWith('-tui.pid'))
    }

    private getPidFilePath(appName: string): string {
        return path.join(this.pidsDirectory, `${appName}.pid`)
    }
}

import { Command } from 'commander'
import { ProcessManager, ConfigManager } from '../services/index.js'
import { isTuiActive, writeSignal, waitForPidState } from '../services/IpcSignal.js'
import { PidManager } from '../services/PidManager.js'
import { getFileNameFriendlyName, pidIsRunning } from '../helpers.js'
import React from 'react'
import { render } from 'ink'
import { ProcessTUI } from '../components/ProcessTUI.js'

export const start = new Command('start')
    .description('start and daemonize an app')
    .argument('<name>', '[name|namespace|file|ecosystem|id...]')
    .option('--no-daemon', 'do not daemonize the app and show interactive TUI')
    .option('--clear-logs', 'clear log files before starting the app')
    .action(async (name, options) => {
        try {
            const configManager = new ConfigManager()
            const processManager = new ProcessManager()

            const config = configManager.readConfig(name)
            configManager.validateConfig(config)

            const runInteractive = options.daemon === false
            let anyTuiActive = false
            const pidManager = new PidManager()

            for (const app of config.apps) {
                if (isTuiActive(app.name)) {
                    anyTuiActive = true
                    const existingPid = pidManager.getPid(getFileNameFriendlyName(app.name))
                    const wasRunning = existingPid !== null && pidIsRunning(existingPid)
                    writeSignal(app.name, 'start')
                    if (!runInteractive) {
                        if (wasRunning) {
                            await waitForPidState(app.name, 'absent', 3000)
                        }
                        const confirmed = await waitForPidState(app.name, 'present', 3000)
                        if (confirmed) {
                            const pid = pidManager.getPid(getFileNameFriendlyName(app.name))
                            console.log(`Started ${app.name} with pid ${pid}`)
                        } else {
                            console.warn(`Start signal sent but could not confirm ${app.name} started within timeout`)
                        }
                    }
                } else {
                    processManager.startApp(app, {
                        daemon: options.daemon,
                        clearLogs: options.clearLogs
                    })
                }
            }

            if (runInteractive && anyTuiActive) {
                console.log('A TUI session is already running in another terminal — not opening a new one')
            }

            if (runInteractive && !anyTuiActive) {
                render(React.createElement(ProcessTUI, {
                    configPath: name,
                    clearLogs: options.clearLogs
                }))
            }
        } catch (error: unknown) {
            const err = error as Error
            console.error(`Error: ${err.message}`)
            process.exit(1)
        }
    })

import * as fs from 'node:fs'
import * as YAML from 'yaml'
import { configSchema } from '../schema.js'

export interface AppConfig {
    name: string
    cwd: string
    run: string
}

export interface Config {
    apps: AppConfig[]
}

export class ConfigManager {
    readConfig(configFilePath: string): Config {
        if (!fs.existsSync(configFilePath)) {
            throw new Error(`Config file not found: ${configFilePath}`)
        }

        try {
            const configContent = fs.readFileSync(configFilePath, 'utf8')
            const configParsed = YAML.parse(configContent)

            const { success, data: config, error } = configSchema.safeParse(configParsed)

            if (!success) {
                throw new Error(`Invalid config file: ${error.message}`)
            }

            return config
        } catch (error: unknown) {
            const err = error as Error
            throw new Error(`Error reading config file: ${err.message}`)
        }
    }

    validateAppConfig(app: AppConfig): void {
        if (!app.name?.trim()) {
            throw new Error('App name is required')
        }

        if (!app.cwd?.trim()) {
            throw new Error(`App '${app.name}' must have a valid working directory`)
        }

        if (!app.run?.trim()) {
            throw new Error(`App '${app.name}' must have a valid run command`)
        }
    }

    validateConfig(config: Config): void {
        if (!config.apps || !Array.isArray(config.apps)) {
            throw new Error('Config must contain an apps array')
        }

        if (config.apps.length === 0) {
            throw new Error('Config must contain at least one app')
        }

        const appNames = new Set<string>()

        for (const app of config.apps) {
            this.validateAppConfig(app)

            if (appNames.has(app.name)) {
                throw new Error(`Duplicate app name found: ${app.name}`)
            }

            appNames.add(app.name)
        }
    }
}

import * as fs from 'node:fs'
import * as path from 'node:path'
import { getProcessSignalPath, getTuiPidPath, getFileNameFriendlyName, pidIsRunning, getPomituPidsDirectory, getTuiReloadSignalPath, getTuiReloadResultPath } from '../helpers.js'
import { PidManager } from './PidManager.js'

export type IpcAction = 'restart' | 'stop' | 'start'

interface SignalPayload {
    action: IpcAction
    timestamp: number
}

const SIGNAL_MAX_AGE_MS = 5000
const WAIT_POLL_INTERVAL_MS = 100

export function writeTuiPresence(appName: string): void {
    const tuiPidPath = getTuiPidPath(getFileNameFriendlyName(appName))
    fs.writeFileSync(tuiPidPath, process.pid.toString())
}

export function clearTuiPresence(appName: string): void {
    const tuiPidPath = getTuiPidPath(getFileNameFriendlyName(appName))
    if (fs.existsSync(tuiPidPath)) {
        fs.unlinkSync(tuiPidPath)
    }
}

const TUI_HEARTBEAT_MAX_AGE_MS = 30000

export function isTuiActive(appName: string): boolean {
    const tuiPidPath = getTuiPidPath(getFileNameFriendlyName(appName))
    if (!fs.existsSync(tuiPidPath)) {
        return false
    }
    try {
        const stat = fs.statSync(tuiPidPath)
        if (Date.now() - stat.mtimeMs > TUI_HEARTBEAT_MAX_AGE_MS) {
            fs.unlinkSync(tuiPidPath)
            return false
        }
        return true
    } catch {
        return false
    }
}

export function isAnyTuiActive(): boolean {
    const pidsDir = getPomituPidsDirectory()
    return fs.readdirSync(pidsDir).some(file => {
        if (!file.endsWith('-tui.pid')) return false
        try {
            return Date.now() - fs.statSync(path.join(pidsDir, file)).mtimeMs <= TUI_HEARTBEAT_MAX_AGE_MS
        } catch {
            return false
        }
    })
}

export interface ReloadResult {
    timestamp: number
    ok: boolean
    message: string
}

export function writeReloadSignal(): number {
    const timestamp = Date.now()
    fs.rmSync(getTuiReloadResultPath(), { force: true })
    fs.writeFileSync(getTuiReloadSignalPath(), JSON.stringify({ timestamp }))
    return timestamp
}

export function clearReloadSignal(): void {
    fs.rmSync(getTuiReloadSignalPath(), { force: true })
}

// Returns the signal's timestamp, which the result echoes back.
export function readAndClearReloadSignal(): number | null {
    const signalPath = getTuiReloadSignalPath()
    if (!fs.existsSync(signalPath)) {
        return null
    }
    try {
        const raw = fs.readFileSync(signalPath, 'utf-8')
        fs.unlinkSync(signalPath)
        const { timestamp } = JSON.parse(raw) as { timestamp: number }
        return Date.now() - timestamp > SIGNAL_MAX_AGE_MS ? null : timestamp
    } catch {
        return null
    }
}

export function writeReloadResult(result: ReloadResult): void {
    fs.writeFileSync(getTuiReloadResultPath(), JSON.stringify(result))
}

export async function waitForReloadResult(timestamp: number, timeoutMs: number): Promise<ReloadResult | null> {
    const resultPath = getTuiReloadResultPath()
    const deadline = Date.now() + timeoutMs
    while (Date.now() < deadline) {
        try {
            const result = JSON.parse(fs.readFileSync(resultPath, 'utf-8')) as ReloadResult
            if (result.timestamp === timestamp) {
                fs.rmSync(resultPath, { force: true })
                return result
            }
        } catch {
            // not written yet
        }
        await new Promise(resolve => setTimeout(resolve, WAIT_POLL_INTERVAL_MS))
    }
    return null
}

export function writeSignal(appName: string, action: IpcAction): void {
    const signalPath = getProcessSignalPath(getFileNameFriendlyName(appName))
    const payload: SignalPayload = { action, timestamp: Date.now() }
    fs.writeFileSync(signalPath, JSON.stringify(payload))
}

export function readAndClearSignal(appName: string): IpcAction | null {
    const signalPath = getProcessSignalPath(getFileNameFriendlyName(appName))
    if (!fs.existsSync(signalPath)) {
        return null
    }
    try {
        const raw = fs.readFileSync(signalPath, 'utf-8')
        fs.unlinkSync(signalPath)
        const payload = JSON.parse(raw) as SignalPayload
        if (Date.now() - payload.timestamp > SIGNAL_MAX_AGE_MS) {
            return null
        }
        return payload.action
    } catch {
        return null
    }
}

export async function waitForPidState(
    appName: string,
    state: 'present' | 'absent',
    timeoutMs = 3000
): Promise<boolean> {
    const pidManager = new PidManager()
    const fileNameFriendlyName = getFileNameFriendlyName(appName)
    const deadline = Date.now() + timeoutMs

    while (Date.now() < deadline) {
        const pid = pidManager.getPid(fileNameFriendlyName)
        const isRunning = pid !== null && pidIsRunning(pid)

        if (state === 'present' && isRunning) return true
        if (state === 'absent' && !isRunning) return true

        await new Promise(resolve => setTimeout(resolve, WAIT_POLL_INTERVAL_MS))
    }

    return false
}

import * as fs from 'node:fs'
import * as path from 'node:path'
import {
    getPomituLogsDirectory,
    getProcessLogOutFilePath,
    getProcessLogErrorFilePath,
    getFileNameFriendlyName
} from '../helpers.js'

export class LogManager {
    private logsDirectory: string

    constructor() {
        this.logsDirectory = getPomituLogsDirectory()
    }

    clearAppLogs(appName: string): void {
        const stdoutPath = getProcessLogOutFilePath(appName)
        const stderrPath = getProcessLogErrorFilePath(appName)

        if (fs.existsSync(stdoutPath)) {
            fs.unlinkSync(stdoutPath)
        }
        if (fs.existsSync(stderrPath)) {
            fs.unlinkSync(stderrPath)
        }
    }

    flushLogs(appName?: string): string[] {
        if (!fs.existsSync(this.logsDirectory)) {
            return []
        }

        let logs = fs.readdirSync(this.logsDirectory)

        if (appName) {
            const fileNameFriendlyName = getFileNameFriendlyName(appName)
            logs = logs.filter((log) => log.startsWith(fileNameFriendlyName))
        }

        const fullLogPaths = logs.map((log) => path.join(this.logsDirectory, log))
        const flushedFiles: string[] = []

        for (const logFilePath of fullLogPaths) {
            if (fs.existsSync(logFilePath)) {
                console.log(`Flushing ${logFilePath}`)
                fs.unlinkSync(logFilePath)
                flushedFiles.push(logFilePath)
            }
        }

        return flushedFiles
    }

    getLogFiles(appName?: string): string[] {
        if (!fs.existsSync(this.logsDirectory)) {
            return []
        }

        let logs = fs.readdirSync(this.logsDirectory)

        if (appName) {
            const fileNameFriendlyName = getFileNameFriendlyName(appName)
            logs = logs.filter((log) => log.startsWith(fileNameFriendlyName))
        }

        return logs.map((log) => path.join(this.logsDirectory, log))
    }
}

import { Command } from 'commander'
import { PidManager } from '../services/PidManager.js'
import { isTuiActive, writeSignal, waitForPidState } from '../services/IpcSignal.js'
import { getFileNameFriendlyName } from '../helpers.js'

export const restart = new Command('restart')
    .description('restart a running app (works whether managed by TUI or daemon)')
    .argument('<name>', 'name of the app to restart')
    .action(async (name) => {
        try {
            if (isTuiActive(name)) {
                writeSignal(name, 'restart')
                await waitForPidState(name, 'absent', 3000)
                const confirmed = await waitForPidState(name, 'present', 3000)
                if (confirmed) {
                    const pidManager = new PidManager()
                    const pid = pidManager.getPid(getFileNameFriendlyName(name))
                    console.log(`Restarted ${name} (PID: ${pid})`)
                } else {
                    console.warn(`Restart signal sent but could not confirm ${name} restarted within timeout`)
                }
            } else {
                console.error(`No active TUI session found for ${name}. For daemon-mode processes, use: pomitu stop ${name} && pomitu start <config>`)
                process.exit(1)
            }
        } catch (error: unknown) {
            const err = error as Error
            console.error(`Error: ${err.message}`)
            process.exit(1)
        }
    })

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react'
import readline from 'node:readline'
import { existsSync } from 'node:fs'
import open from 'open'
import { Box, Text, useApp, useStdin, useInput } from 'ink'
import { PersistentSelectInput } from './PersistentSelectInput.js'
import { ProcessManager, ConfigManager } from '../services/index.js'
import { getFileNameFriendlyName, getProcessLogOutFilePath, getProcessLogErrorFilePath, getPomituSignalsDirectory, getTuiReloadSignalPath } from '../helpers.js'
import chokidar from 'chokidar'
import * as path from 'node:path'
import { writeTuiPresence, clearTuiPresence, readAndClearSignal, readAndClearReloadSignal, writeReloadResult } from '../services/IpcSignal.js'
import type { AppConfig } from '../services/ConfigManager.js'

interface ProcessTUIProps {
    configPath: string
    clearLogs?: boolean
}

interface ProcessStatus {
    name: string
    pid: number | null
    isRunning: boolean
}

export function ProcessTUI({ configPath, clearLogs }: ProcessTUIProps) {
    const { exit } = useApp()
    const { stdin, setRawMode } = useStdin()
    const [processes, setProcesses] = useState<ProcessStatus[]>([])
    const [apps, setApps] = useState<AppConfig[]>([])
    const [message, setMessage] = useState<string>('')
    const [messageColor, setMessageColor] = useState<'green' | 'red' | 'yellow'>('green')
    const [isProcessing, setIsProcessing] = useState(false)
    const [isReloading, setIsReloading] = useState(false)
    const [searchActive, setSearchActive] = useState(false)
    const [searchQuery, setSearchQuery] = useState('')
    // ESC via Ink's own pipeline — no readline disambiguation delay
    useInput(useCallback((_input: string, key: { escape: boolean }) => {
        if (key.escape) {
            setSearchActive(false)
            setSearchQuery('')
        }
    }, []), { isActive: searchActive })

    const previousRawModeRef = useRef(false)
    const rawModeCapturedRef = useRef(false)
    const appsRef = useRef<AppConfig[]>([])
    const ipcHandlerRef = useRef<((appName: string, action: string) => void) | null>(null)
    const reloadConfigRef = useRef<(() => Promise<{ ok: boolean, message: string }>) | null>(null)

    // Create managers only once
    const processManager = useMemo(() => new ProcessManager(), [])
    const configManager = useMemo(() => new ConfigManager(), [])

    // Function to open file in native app
    const openFileInNativeApp = useCallback(async (filePath: string) => {
        if (!existsSync(filePath)) {
            setMessage(`Log file not found: ${filePath}`)
            setMessageColor('red')
            setTimeout(() => setMessage(''), 3000)
            return
        }

        try {
            await open(filePath)
            setMessage('Opening log file...')
            setMessageColor('green')
        } catch (error) {
            setMessage(`Failed to open log: ${error instanceof Error ? error.message : String(error)}`)
            setMessageColor('red')
        }
        setTimeout(() => setMessage(''), 3000)
    }, [])

    const cleanExit = useCallback(() => {
        appsRef.current.forEach(app => clearTuiPresence(app.name))
        if (setRawMode) {
            setRawMode(previousRawModeRef.current)
        }

        exit()
        process.exit(0)
    }, [exit, setRawMode])

    const computeStatuses = useCallback((): ProcessStatus[] => {
        if (apps.length === 0) {
            return []
        }

        const runningProcesses = processManager.listRunningProcesses()

        return apps.map(app => {
            const fileNameFriendlyName = getFileNameFriendlyName(app.name)
            const running = runningProcesses.find(p => p.name === fileNameFriendlyName)

            return {
                name: app.name,
                pid: running?.pid ?? null,
                isRunning: running?.isRunning ?? false
            }
        })
    }, [apps, processManager])

    // Reload config function
    const reloadConfig = useCallback(async (): Promise<{ ok: boolean, message: string }> => {
        if (isReloading || isProcessing) return { ok: false, message: 'Busy with another operation, try again' }

        setIsReloading(true)
        setMessage('Reloading configuration...')
        setMessageColor('yellow')

        let result: { ok: boolean, message: string }
        try {
            const config = configManager.readConfig(configPath)
            configManager.validateConfig(config)

            // Check for removed apps and stop them if running
            const oldAppNames = new Set(apps.map(app => app.name))
            const newAppNames = new Set(config.apps.map(app => app.name))

            const removedApps = Array.from(oldAppNames).filter(name => !newAppNames.has(name))

            const stoppedApps: string[] = []
            if (removedApps.length > 0) {
                // Check which removed apps are actually running
                const currentProcesses = processes.filter(p =>
                    removedApps.includes(p.name) && p.isRunning
                )

                if (currentProcesses.length > 0) {
                    setMessage(`Stopping removed apps: ${currentProcesses.map(p => p.name).join(', ')}...`)

                    for (const proc of currentProcesses) {
                        try {
                            const success = await processManager.stopApp(proc.name, { quiet: true })
                            if (success) {
                                stoppedApps.push(proc.name)
                            }
                        } catch (error: unknown) {
                            // Continue even if stop fails
                            console.error(`Failed to stop ${proc.name}:`, error)
                        }
                    }
                }
            }

            setApps(config.apps)

            if (stoppedApps.length > 0) {
                result = { ok: true, message: `Configuration reloaded. Stopped ${stoppedApps.length} running app(s): ${stoppedApps.join(', ')}` }
            } else if (removedApps.length > 0) {
                result = { ok: true, message: `Configuration reloaded. ${removedApps.length} app(s) removed (none were running)` }
            } else {
                result = { ok: true, message: 'Configuration reloaded successfully' }
            }
            setMessage(result.message)
            setMessageColor('green')
        } catch (error: unknown) {
            const err = error as Error
            result = { ok: false, message: `Error reloading config: ${err.message}` }
            setMessage(result.message)
            setMessageColor('red')
        } finally {
            setIsReloading(false)
            // Clear message after 3 seconds
            setTimeout(() => setMessage(''), 3000)
        }
        return result
    }, [configPath, configManager, isReloading, isProcessing, apps, processes, processManager])

    useEffect(() => {
        reloadConfigRef.current = reloadConfig
    }, [reloadConfig])

    // Load config on mount
    useEffect(() => {
        try {
            const config = configManager.readConfig(configPath)
            configManager.validateConfig(config)
            setApps(config.apps)
        } catch (error: unknown) {
            const err = error as Error
            setMessage(`Error loading config: ${err.message}`)
            setMessageColor('red')
        }
    }, [configPath, configManager])

    // Update process status
    useEffect(() => {
        setProcesses(computeStatuses())
    }, [computeStatuses])

    // Sync appsRef and write TUI presence files whenever apps change
    useEffect(() => {
        appsRef.current = apps
        apps.forEach(app => writeTuiPresence(app.name))
    }, [apps])

    // Heartbeat: refresh TUI presence file mtimes so isTuiActive can detect stale files
    useEffect(() => {
        const interval = setInterval(() => {
            appsRef.current.forEach(app => writeTuiPresence(app.name))
        }, 10000)
        return () => clearInterval(interval)
    }, [])

    // Set up chokidar watcher for IPC signals (mounted once; uses refs for latest state)
    useEffect(() => {
        const signalsDir = getPomituSignalsDirectory()
        const watcher = chokidar.watch(signalsDir, { ignoreInitial: true })

        const handleSignalFile = (filePath: string) => {
            if (path.resolve(filePath) === path.resolve(getTuiReloadSignalPath())) {
                const timestamp = readAndClearReloadSignal()
                if (timestamp === null || !reloadConfigRef.current) return
                // A failed write only leaves the CLI to time out; it must not crash the TUI.
                reloadConfigRef.current()
                    .then(result => writeReloadResult({ timestamp, ...result }))
                    .catch(() => {})
                return
            }
            if (path.extname(filePath) !== '.json') return
            const fileBaseName = path.basename(filePath, '.json')
            const matchedApp = appsRef.current.find(a => getFileNameFriendlyName(a.name) === fileBaseName)
            if (!matchedApp) return
            const action = readAndClearSignal(matchedApp.name)
            if (!action) return
            if (ipcHandlerRef.current) {
                ipcHandlerRef.current(matchedApp.name, action)
            }
        }

        watcher.on('add', handleSignalFile)
        watcher.on('change', handleSignalFile)

        return () => {
            watcher.close()
        }
    }, [])

    // Handle keyboard input - use keypress events to intercept BEFORE SelectInput
    useEffect(() => {
        if (!stdin) return

        // Enable keypress events and raw mode for immediate key detection
        readline.emitKeypressEvents(stdin)

        const stream = stdin as NodeJS.ReadStream
        if (!rawModeCapturedRef.current) {
            const previousRawMode = typeof stream.isRaw === 'boolean' ? stream.isRaw : false
            previousRawModeRef.current = previousRawMode
            rawModeCapturedRef.current = true
        }

        if (setRawMode) {
            setRawMode(true)
        }

        const handleKeypress = (str: string | undefined, key: readline.Key | undefined) => {
            if (key?.ctrl && key.name === 'c') {
                cleanExit()
                return
            }

            if (searchActive) {
                if (key?.name === 'backspace') {
                    setSearchQuery(prev => prev.slice(0, -1))
                    return
                }
                if (key?.name !== 'return' && str && str.length === 1 && !key?.ctrl && !key?.meta) {
                    setSearchQuery(prev => prev + str)
                }
                // ESC is handled by useInput (Ink pipeline); arrow keys, Enter, and other
                // navigation are handled by PersistentSelectInput via Ink's input pipeline
                return
            }

            if (str === 'q') {
                cleanExit()
            }

            if (str === 'r') {
                reloadConfig()
            }

            if (str === 'e') {
                open(configPath).catch(error => {
                    setMessage(`Failed to open config: ${error instanceof Error ? error.message : String(error)}`)
                    setMessageColor('red')
                    setTimeout(() => setMessage(''), 3000)
                })
            }

            if (str === '/') {
                setSearchActive(true)
                setSearchQuery('')
            }
        }

        // Use prependListener to capture keys before other handlers
        stdin.prependListener('keypress', handleKeypress)

        return () => {
            stdin.removeListener('keypress', handleKeypress)

            if (setRawMode) {
                setRawMode(previousRawModeRef.current)
            }
        }
    }, [stdin, setRawMode, cleanExit, reloadConfig, searchActive])

    // Handle Ctrl+C signal directly - use prependListener to be first
    useEffect(() => {
        const handleSigInt = () => {
            cleanExit()
        }

        // Use prependListener to ensure we handle SIGINT before Ink does
        process.prependListener('SIGINT', handleSigInt)

        return () => {
            process.removeListener('SIGINT', handleSigInt)
        }
    }, [cleanExit])

    const handleSelect = useCallback(async (item: { label: string; value: string }) => {
        if (isProcessing || isReloading) return // Prevent multiple simultaneous operations

        const colonIndex = item.value.indexOf(':')
        const action = item.value.slice(0, colonIndex)
        const appName = item.value.slice(colonIndex + 1)
        const app = apps.find(a => a.name === appName)

        if (!app) {
            setMessage(`App ${appName} not found`)
            setMessageColor('red')
            return
        }

        setIsProcessing(true)

        try {
            if (action === 'start') {
                await processManager.startApp(app, {
                    daemon: false,
                    clearLogs: clearLogs ?? false
                })
                setMessage(`Started ${appName}`)
                setMessageColor('green')
            } else if (action === 'stop') {
                const success = await processManager.stopApp(appName, { quiet: true })
                if (success) {
                    setMessage(`Stopped ${appName}`)
                    setMessageColor('green')
                } else {
                    setMessage(`Failed to stop ${appName}`)
                    setMessageColor('red')
                }
            } else if (action === 'restart') {
                const wasRunning = await processManager.stopApp(appName, { quiet: true })
                if (wasRunning) {
                    // Wait a bit before restarting
                    await new Promise(resolve => setTimeout(resolve, 500))
                }
                await processManager.startApp(app, {
                    daemon: false,
                    clearLogs: clearLogs ?? false
                })
                setMessage(`Restarted ${appName}`)
                setMessageColor('green')
            } else if (action === 'viewout') {
                const fileNameFriendly = getFileNameFriendlyName(appName)
                const logPath = getProcessLogOutFilePath(fileNameFriendly)
                openFileInNativeApp(logPath)
                setIsProcessing(false)
                return
            } else if (action === 'viewerr') {
                const fileNameFriendly = getFileNameFriendlyName(appName)
                const logPath = getProcessLogErrorFilePath(fileNameFriendly)
                openFileInNativeApp(logPath)
                setIsProcessing(false)
                return
            } else if (action === 'opencwd') {
                try {
                    await open(app.cwd)
                    setMessage('Opening working directory...')
                    setMessageColor('green')
                } catch (error) {
                    setMessage(`Failed to open directory: ${error instanceof Error ? error.message : String(error)}`)
                    setMessageColor('red')
                }
                setTimeout(() => setMessage(''), 3000)
                setIsProcessing(false)
                return
            }

            setProcesses(computeStatuses())
        } catch (error: unknown) {
            const err = error as Error
            setMessage(`Error: ${err.message}`)
            setMessageColor('red')
        } finally {
            setIsProcessing(false)
        }

        // Clear message after 3 seconds
        setTimeout(() => setMessage(''), 3000)
    }, [apps, clearLogs, computeStatuses, processManager, isProcessing, isReloading])

    const buildMenuItems = useCallback((statuses: ProcessStatus[]) => {
        const items: Array<{ label: string; value: string }> = []

        statuses.forEach(proc => {
            const statusLabel = proc.isRunning
                ? `🟢 Running (PID: ${proc.pid})`
                : '🔴 Stopped'

            items.push({
                label: `${proc.name.padEnd(40)} ${statusLabel}`,
                value: `info:${proc.name}`
            })

            if (proc.isRunning) {
                items.push({
                    label: `  ├─ Stop ${proc.name}`,
                    value: `stop:${proc.name}`
                })
                items.push({
                    label: `  ├─ Restart ${proc.name}`,
                    value: `restart:${proc.name}`
                })
                items.push({
                    label: '  ├─ View Output Log',
                    value: `viewout:${proc.name}`
                })
                items.push({
                    label: '  ├─ View Error Log',
                    value: `viewerr:${proc.name}`
                })
                items.push({
                    label: '  └─ Open Working Directory',
                    value: `opencwd:${proc.name}`
                })
            } else {
                items.push({
                    label: `  ├─ Start ${proc.name}`,
                    value: `start:${proc.name}`
                })
                items.push({
                    label: '  ├─ View Output Log',
                    value: `viewout:${proc.name}`
                })
                items.push({
                    label: '  ├─ View Error Log',
                    value: `viewerr:${proc.name}`
                })
                items.push({
                    label: '  └─ Open Working Directory',
                    value: `opencwd:${proc.name}`
                })
            }
        })

        return items
    }, [])

    const allItems = useMemo(() => buildMenuItems(processes), [buildMenuItems, processes])

    const items = useMemo(() => {
        if (!searchQuery) return allItems

        const query = searchQuery.toLowerCase()
        return allItems.filter(item =>
            item.label.toLowerCase().includes(query) ||
            item.value.toLowerCase().includes(query)
        )
    }, [allItems, searchQuery])

    const handleMenuSelect = useCallback((item: { label: string; value: string }) => {
        if (item.value === 'separator' || item.value.startsWith('info:')) {
            // Informational rows are read-only
        } else {
            handleSelect(item)
        }
    }, [handleSelect])

    // Keep IPC signal handler up to date with current handleSelect
    useEffect(() => {
        ipcHandlerRef.current = (appName: string, action: string) => {
            handleSelect({ label: '', value: `${action}:${appName}` })
        }
    }, [handleSelect])

    const notificationText = isProcessing ? 'Processing...' : (isReloading ? 'Reloading...' : message)
    const notificationColor = (isProcessing || isReloading) ? 'yellow' : message ? messageColor : undefined

    return (
        <Box flexDirection="column">
            <Box borderStyle="round" borderColor="cyan" padding={1} marginBottom={1}>
                <Text bold color="cyan">Pomitu Process Manager - Interactive Mode</Text>
            </Box>

            {processes.length > 0 ? (
                <>
                    <Box marginBottom={1}>
                        <Text dimColor>Use arrow keys to navigate, Enter to select, '/' to search, 'r' to reload, 'e' to edit config, 'q' or Ctrl+C to quit</Text>
                    </Box>
                    {searchActive && (
                        <Box marginBottom={1}>
                            <Text color="yellow">Search: {searchQuery}</Text>
                            <Text dimColor> (ESC to clear)</Text>
                        </Box>
                    )}
                    {searchActive && searchQuery && items.length < allItems.length && (
                        <Box marginBottom={1}>
                            <Text dimColor>Showing {items.length} of {allItems.length} items</Text>
                        </Box>
                    )}
                    {!searchActive && items.length > 15 && (
                        <Box marginBottom={1}>
                            <Text dimColor>Showing 15 of {items.length} items - scroll with ↑↓ arrows</Text>
                        </Box>
                    )}
                    <PersistentSelectInput items={items} onSelect={handleMenuSelect} isFocused={!isProcessing && !isReloading} limit={15} headingPredicate={item => item.value.startsWith('info:')} />
                </>
            ) : (
                <Text>Loading processes...</Text>
            )}

            <Box marginTop={1}>
                <Text color={notificationColor ?? 'gray'}>{notificationText ?? ' '}</Text>
            </Box>
        </Box>
    )
}

/**
 * Drop-in replacement for ink-select-input's SelectInput that preserves scroll
 * position when items change, instead of resetting to the top.
 */
import { isDeepStrictEqual } from 'node:util'
import React, { useState, useEffect, useRef, useCallback } from 'react'
import { Box, useInput, useStdin } from 'ink'
import { Indicator, Item as ItemComponent } from 'ink-select-input'
import type { IndicatorProps, ItemProps } from 'ink-select-input'
import type { FC } from 'react'

type SelectItem<V> = {
    key?: string
    label: string
    value: V
}

type Props<V> = {
    items?: Array<SelectItem<V>>
    isFocused?: boolean
    initialIndex?: number
    limit?: number
    indicatorComponent?: FC<IndicatorProps>
    itemComponent?: FC<ItemProps>
    onSelect?: (item: SelectItem<V>) => void
    onHighlight?: (item: SelectItem<V>) => void
    headingPredicate?: (item: SelectItem<V>) => boolean
}

function rotateArray<T>(arr: T[], k: number): T[] {
    if (arr.length === 0) return arr
    const n = arr.length
    const steps = ((k % n) + n) % n
    if (steps === 0) return [...arr]
    return [...arr.slice(-steps), ...arr.slice(0, -steps)]
}

export function PersistentSelectInput<V>({
    items = [],
    isFocused = true,
    initialIndex = 0,
    indicatorComponent: IndicatorComp = Indicator as FC<IndicatorProps>,
    itemComponent: ItemComp = ItemComponent as FC<ItemProps>,
    limit: customLimit,
    onSelect,
    onHighlight,
    headingPredicate,
}: Props<V>) {
    const hasLimit = typeof customLimit === 'number' && items.length > customLimit
    const limit = hasLimit ? Math.min(customLimit, items.length) : items.length
    const lastIndex = limit - 1

    const [rotateIndex, setRotateIndex] = useState(
        initialIndex > lastIndex ? lastIndex - initialIndex : 0
    )
    const [selectedIndex, setSelectedIndex] = useState(
        initialIndex ? (initialIndex > lastIndex ? lastIndex : initialIndex) : 0
    )

    const previousItems = useRef(items)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { internal_eventEmitter } = useStdin() as any

    useEffect(() => {
        if (!isFocused || items.length === 0) return

        const handleHomeEnd = (data: Buffer) => {
            const str = data.toString()
            const isHome = str === '\x1b[H' || str === '\x1bOH' || str === '\x1b[1~' || str === '\x1b[7~'
            const isEnd = str === '\x1b[F' || str === '\x1bOF' || str === '\x1b[4~' || str === '\x1b[8~'

            if (isHome) {
                setSelectedIndex(0)
                setRotateIndex(0)
                if (typeof onHighlight === 'function' && items[0]) onHighlight(items[0])
            }

            if (isEnd) {
                if (hasLimit) {
                    const newRotateIndex = -(items.length - limit)
                    setRotateIndex(newRotateIndex)
                    setSelectedIndex(limit - 1)
                    const sliced = rotateArray(items, newRotateIndex).slice(0, limit)
                    if (typeof onHighlight === 'function' && sliced[limit - 1]) onHighlight(sliced[limit - 1])
                } else {
                    const lastIdx = items.length - 1
                    setSelectedIndex(lastIdx)
                    if (typeof onHighlight === 'function' && items[lastIdx]) onHighlight(items[lastIdx])
                }
            }
        }

        internal_eventEmitter?.on('input', handleHomeEnd)
        return () => {
            internal_eventEmitter?.removeListener('input', handleHomeEnd)
        }
    }, [isFocused, items, hasLimit, limit, onHighlight, internal_eventEmitter])

    useEffect(() => {
        if (!isDeepStrictEqual(
            previousItems.current.map(item => item.value),
            items.map(item => item.value)
        )) {
            const newHasLimit = typeof customLimit === 'number' && items.length > customLimit
            if (newHasLimit) {
                // Clamp scroll and cursor to new valid bounds
                const maxScroll = items.length - customLimit!
                setRotateIndex(prev => Math.max(-maxScroll, Math.min(0, prev)))
                setSelectedIndex(prev => Math.min(prev, customLimit! - 1))
            } else {
                // No scrolling needed anymore
                setRotateIndex(0)
                setSelectedIndex(prev => Math.min(prev, Math.max(0, items.length - 1)))
            }
        }
        previousItems.current = items
    }, [items, customLimit])

    useInput(useCallback((input, key) => {
        if (input === 'k' || key.upArrow) {
            const atVisualTop = selectedIndex === 0
            if (hasLimit) {
                if (atVisualTop) {
                    if (rotateIndex < 0) {
                        // Scroll window up
                        const nextRotateIndex = rotateIndex + 1
                        setRotateIndex(nextRotateIndex)
                        const sliced = rotateArray(items, nextRotateIndex).slice(0, limit)
                        if (typeof onHighlight === 'function' && sliced[0]) onHighlight(sliced[0])
                    }
                    // else: already at absolute top, do nothing
                } else {
                    const nextSelectedIndex = selectedIndex - 1
                    setSelectedIndex(nextSelectedIndex)
                    const sliced = rotateArray(items, rotateIndex).slice(0, limit)
                    if (typeof onHighlight === 'function' && sliced[nextSelectedIndex]) onHighlight(sliced[nextSelectedIndex])
                }
            } else {
                // No limit: wrap around
                const nextSelectedIndex = atVisualTop ? items.length - 1 : selectedIndex - 1
                setSelectedIndex(nextSelectedIndex)
                if (typeof onHighlight === 'function' && items[nextSelectedIndex]) onHighlight(items[nextSelectedIndex])
            }
        }

        if (input === 'j' || key.downArrow) {
            const atVisualBottom = selectedIndex === (hasLimit ? limit : items.length) - 1
            if (hasLimit) {
                const atAbsBottom = rotateIndex <= -(items.length - limit)
                if (atVisualBottom) {
                    if (!atAbsBottom) {
                        // Scroll window down
                        const nextRotateIndex = rotateIndex - 1
                        setRotateIndex(nextRotateIndex)
                        const sliced = rotateArray(items, nextRotateIndex).slice(0, limit)
                        if (typeof onHighlight === 'function' && sliced[limit - 1]) onHighlight(sliced[limit - 1])
                    }
                    // else: already at absolute bottom, do nothing
                } else {
                    const nextSelectedIndex = selectedIndex + 1
                    setSelectedIndex(nextSelectedIndex)
                    const sliced = rotateArray(items, rotateIndex).slice(0, limit)
                    if (typeof onHighlight === 'function' && sliced[nextSelectedIndex]) onHighlight(sliced[nextSelectedIndex])
                }
            } else {
                // No limit: wrap around
                const nextSelectedIndex = atVisualBottom ? 0 : selectedIndex + 1
                setSelectedIndex(nextSelectedIndex)
                if (typeof onHighlight === 'function' && items[nextSelectedIndex]) onHighlight(items[nextSelectedIndex])
            }
        }

        if (key.pageUp || key.pageDown) {
            const absIndex = hasLimit ? -rotateIndex + selectedIndex : selectedIndex
            let targetAbs = -1

            if (headingPredicate) {
                if (key.pageUp) {
                    for (let i = absIndex - 1; i >= 0; i--) {
                        if (items[i] && headingPredicate(items[i]!)) { targetAbs = i; break }
                    }
                } else {
                    for (let i = absIndex + 1; i < items.length; i++) {
                        if (items[i] && headingPredicate(items[i]!)) { targetAbs = i; break }
                    }
                }
            } else {
                targetAbs = key.pageUp
                    ? Math.max(absIndex - limit, 0)
                    : Math.min(absIndex + limit, items.length - 1)
            }

            if (targetAbs < 0) return

            if (hasLimit) {
                const windowStart = -rotateIndex
                let newWindowStart: number
                if (targetAbs < windowStart) {
                    newWindowStart = targetAbs
                } else if (targetAbs >= windowStart + limit) {
                    newWindowStart = Math.min(targetAbs, items.length - limit)
                } else {
                    newWindowStart = windowStart
                }
                const newRotateIndex = -newWindowStart
                const newSelectedIndex = targetAbs - newWindowStart
                setRotateIndex(newRotateIndex)
                setSelectedIndex(newSelectedIndex)
                const sliced = rotateArray(items, newRotateIndex).slice(0, limit)
                if (typeof onHighlight === 'function' && sliced[newSelectedIndex]) onHighlight(sliced[newSelectedIndex])
            } else {
                setSelectedIndex(targetAbs)
                if (typeof onHighlight === 'function' && items[targetAbs]) onHighlight(items[targetAbs]!)
            }
        }

        if (/^[1-9]$/.test(input)) {
            const targetIndex = Number.parseInt(input, 10) - 1
            const visibleItems = hasLimit
                ? rotateArray(items, rotateIndex).slice(0, limit)
                : items
            if (targetIndex >= 0 && targetIndex < visibleItems.length) {
                const selectedItem = visibleItems[targetIndex]
                if (selectedItem) {
                    onSelect?.(selectedItem)
                }
            }
        }

        if (key.return) {
            const slicedItems = hasLimit
                ? rotateArray(items, rotateIndex).slice(0, limit)
                : items
            if (typeof onSelect === 'function') {
                onSelect(slicedItems[selectedIndex])
            }
        }
    }, [hasLimit, limit, rotateIndex, selectedIndex, items, onSelect, onHighlight, headingPredicate]), { isActive: isFocused })

    const slicedItems = hasLimit
        ? rotateArray(items, rotateIndex).slice(0, limit)
        : items

    return (
        <Box flexDirection="column">
            {slicedItems.map((item, index) => {
                const isSelected = index === selectedIndex
                return (
                    <Box key={(item as any).key ?? String(item.value)}>
                        <IndicatorComp isSelected={isSelected} />
                        <ItemComp isSelected={isSelected} label={item.label} />
                    </Box>
                )
            })}
        </Box>
    )
}
